func TestRoles(t *testing.T) {
	for _, c := range []struct {
		route string
		role  string
		req   apiCase
	}{
		{"create_invoice", "member", createInvoiceBaseline},
		{"add_line", "member", addLineBaseline},
		{"issue_invoice", "member", issueInvoiceBaseline},
		{"record_payment", "member", recordPaymentBaseline},
		{"void_invoice", "member", voidInvoiceBaseline},
		{"invoice_total", "member", invoiceTotalBaseline},
	} {
		t.Run(c.route, func(t *testing.T) {
			svc := &fakeService{}
			wantProblem(t, do(svc, "", c.req), http.StatusUnauthorized)
			wantProblem(t, do(svc, "nobody", c.req), http.StatusForbidden)
			if len(svc.calls) != 0 {
				t.Fatalf("the service was called without the role: %v", svc.calls)
			}
			if rec := do(svc, c.role, c.req); rec.Code >= 400 {
				t.Fatalf("the route's own role was refused: %d %s", rec.Code, rec.Body)
			}
		})
	}
}

// TestRouteTable: the table lists every route once, in the mux's own terms.
func TestRouteTable(t *testing.T) {
	if len(Routes) != 6 {
		t.Fatalf("%d routes, want 6", len(Routes))
	}
	if r := Routes[0]; r.Name != "create_invoice" || r.Method != "POST" || r.Path != "/invoices" || r.Role != "member" || r.Call != "new_invoice" || r.Status != 201 {
		t.Errorf("Routes[0] = %+v", r)
	}
	if r := Routes[1]; r.Name != "add_line" || r.Method != "POST" || r.Path != "/invoices/{id}/lines" || r.Role != "member" || r.Call != "Invoice.add_line" || r.Status != 200 {
		t.Errorf("Routes[1] = %+v", r)
	}
	if r := Routes[2]; r.Name != "issue_invoice" || r.Method != "POST" || r.Path != "/invoices/{id}/issue" || r.Role != "member" || r.Call != "Invoice.issue" || r.Status != 200 {
		t.Errorf("Routes[2] = %+v", r)
	}
	if r := Routes[3]; r.Name != "record_payment" || r.Method != "POST" || r.Path != "/invoices/{id}/payments" || r.Role != "member" || r.Call != "Invoice.record_payment" || r.Status != 200 {
		t.Errorf("Routes[3] = %+v", r)
	}
	if r := Routes[4]; r.Name != "void_invoice" || r.Method != "POST" || r.Path != "/invoices/{id}/void" || r.Role != "member" || r.Call != "Invoice.void" || r.Status != 204 {
		t.Errorf("Routes[4] = %+v", r)
	}
	if r := Routes[5]; r.Name != "invoice_total" || r.Method != "GET" || r.Path != "/invoices/{id}/total" || r.Role != "member" || r.Call != "total" || r.Status != 200 {
		t.Errorf("Routes[5] = %+v", r)
	}
}

func TestUnknownRoutes(t *testing.T) {
	svc := &fakeService{}
	if rec := do(svc, "member", apiCase{method: "GET", target: "/no-such-route"}); rec.Code != http.StatusNotFound {
		t.Errorf("unknown path: status %d", rec.Code)
	}
	if len(svc.calls) != 0 {
		t.Errorf("the service was called: %v", svc.calls)
	}
}

// TestServiceErrors: what a Service returns decides the status, and an
// unexpected error says nothing about its cause.
func TestServiceErrors(t *testing.T) {
	for _, c := range []struct {
		name string
		err  error
		want int
	}{
		{"not found", ErrNotFound, http.StatusNotFound},
		{"wrapped not found", fmt.Errorf("loading: %w", ErrNotFound), http.StatusNotFound},
		{"conflict", fmt.Errorf("storing: %w", ErrConflict), http.StatusConflict},
		{"unprocessable", fmt.Errorf("checking: %w", ErrUnprocessable), http.StatusUnprocessableEntity},
		{"acme forbidden", acme.ErrForbidden, http.StatusConflict},
		{"acme no transition", fmt.Errorf("step: %w", acme.ErrNoTransition), http.StatusConflict},
		{"acme invariant", &acme.InvariantError{Entity: "E", Invariant: "i"}, http.StatusUnprocessableEntity},
		{"anything else", errors.New("database password is hunter2"), http.StatusInternalServerError},
	} {
		t.Run(c.name, func(t *testing.T) {
			svc := &fakeService{err: c.err}
			rec := do(svc, "member", createInvoiceBaseline)
			wantProblem(t, rec, c.want)
			if strings.Contains(rec.Body.String(), "hunter2") {
				t.Fatalf("the response leaks the error: %s", rec.Body)
			}
		})
	}
}

func sameJSON(t *testing.T, got, want string) {
	t.Helper()
	var a, b any
	if err := json.Unmarshal([]byte(got), &a); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal([]byte(want), &b); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(a, b) {
		t.Fatalf("got %s, want %s", got, want)
	}
}

func TestWireAcmeInvoice_RoundTrip(t *testing.T) {
	in := "{\"currency\":\"eur\",\"customer\":\"a\",\"id\":\"a\",\"issued_at\":\"2026-01-01T00:00:00Z\",\"lines\":[{\"description\":\"a\",\"quantity\":1,\"unit_price\":1}],\"number\":\"a\",\"paid\":1,\"void_reason\":\"a\"}"
	var wv wireAcmeInvoice
	if err := json.Unmarshal([]byte(in), &wv); err != nil {
		t.Fatal(err)
	}
	var p problems
	d := decodeAcmeInvoice(wv, "", &p)
	if p.any() {
		t.Fatalf("a valid sample has problems: %v", p.list)
	}
	out, err := json.Marshal(encodeAcmeInvoice(d))
	if err != nil {
		t.Fatal(err)
	}
	sameJSON(t, string(out), in)
}

